# Write your MySQL query statement below
SELECT p.product_name, SUM(o.unit) as unit FROM Products p LEFT JOIN Orders o ON p.product_id=o.product_id WHERE o.order_date BETWEEN '2020-02-01' AND '2020-02-29' GROUP BY p.product_id HAVING SUM(o.unit)>=100;
/*SELECT p.product_name, SUM(o.unit) as unit FROM Products p LEFT JOIN Orders o ON p.product_id=o.product_id WHERE DATEDIFF('2020-02-29',o.order_date) BETWEEN 1 and 28 GROUP BY p.product_id HAVING SUM(o.unit)>=100;*/ 